-- Fixed C4 structure observation; no row bodies or sequence current values.
WITH selected AS MATERIALIZED (
 SELECT c.oid,c.relname,n.nspname FROM pg_catalog.pg_class c
 JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname=ANY($1::text[]) AND c.relkind IN ('r','p')
), constraints AS MATERIALIZED (
 SELECT k.* FROM pg_catalog.pg_constraint k JOIN selected s ON s.oid=k.conrelid
), structure AS MATERIALIZED (
 SELECT jsonb_build_object('schemaVersion',1,
 'relations',COALESCE((SELECT jsonb_agg(jsonb_build_object(
  'schema',s.nspname,'relation',s.relname,'oid',s.oid::text,
  'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('position',a.attnum,'name',a.attname,'typeOid',a.atttypid::text,'typeSchema',tn.nspname,'typeKind',t.typtype,'baseOid',t.typbasetype::text,'typmod',a.atttypmod,'nullable',NOT a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'defaultExpression',pg_get_expr(ad.adbin,ad.adrelid)) ORDER BY a.attnum)
   FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace tn ON tn.oid=t.typnamespace LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum WHERE a.attrelid=s.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'::jsonb),
  'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('oid',k.oid::text,'name',k.conname,'kind',k.contype,'definition',pg_get_constraintdef(k.oid,false),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred,'key',COALESCE(to_jsonb(k.conkey),'[]'::jsonb),'foreignOid',k.confrelid::text,'foreignKey',COALESCE(to_jsonb(k.confkey),'[]'::jsonb),'updateAction',k.confupdtype,'deleteAction',k.confdeltype,'match',k.confmatchtype,'indexOid',k.conindid::text,
   'dependencies',COALESCE((SELECT jsonb_agg(jsonb_build_object('class',d.refclassid::regclass::text,'oid',d.refobjid::text,'subid',d.refobjsubid,'kind',d.deptype,'description',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'metadataSha256',CASE WHEN d.refclassid='pg_proc'::regclass THEN (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid=d.refobjid) WHEN d.refclassid='pg_type'::regclass THEN (SELECT encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') FROM pg_type t WHERE t.oid=d.refobjid) WHEN d.refclassid='pg_operator'::regclass THEN (SELECT encode(sha256(convert_to(to_jsonb(o)::text,'UTF8')),'hex') FROM pg_operator o WHERE o.oid=d.refobjid) WHEN d.refclassid='pg_collation'::regclass THEN (SELECT encode(sha256(convert_to(to_jsonb(o)::text,'UTF8')),'hex') FROM pg_collation o WHERE o.oid=d.refobjid) WHEN d.refclassid='pg_class'::regclass THEN (SELECT encode(sha256(convert_to(jsonb_build_object('schema',n.nspname,'relation',r.relname,'kind',r.relkind)::text,'UTF8')),'hex') FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE r.oid=d.refobjid) ELSE NULL END) ORDER BY d.refclassid,d.refobjid,d.refobjsubid,d.deptype) FROM pg_depend d WHERE d.classid='pg_constraint'::regclass AND d.objid=k.oid),'[]'::jsonb)) ORDER BY k.conname COLLATE "C",k.oid) FROM constraints k WHERE k.conrelid=s.oid),'[]'::jsonb)
 ) ORDER BY s.nspname COLLATE "C",s.relname COLLATE "C") FROM selected s),'[]'::jsonb),
 'domains',COALESCE((SELECT jsonb_agg(t.oid::text ORDER BY t.oid) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE t.typtype='d' AND (n.nspname=ANY($1::text[]) OR t.oid IN(SELECT a.atttypid FROM pg_attribute a JOIN selected s ON s.oid=a.attrelid WHERE a.attnum>0 AND NOT a.attisdropped))),'[]'::jsonb),
 'sequences',COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',c.relname,'oid',c.oid::text,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'persistence',c.relpersistence,'typeOid',q.seqtypid::text,'start',q.seqstart::text,'increment',q.seqincrement::text,'minimum',q.seqmin::text,'maximum',q.seqmax::text,'cache',q.seqcache::text,'cycle',q.seqcycle,
  'dependencies',COALESCE((SELECT jsonb_agg(jsonb_build_object('class',d.classid::regclass::text,'objid',d.objid::text,'objsubid',d.objsubid,'refclass',d.refclassid::regclass::text,'refobjid',d.refobjid::text,'refsubid',d.refobjsubid,'kind',d.deptype,'schema',rn.nspname,'relation',rc.relname,'column',a.attname,'identity',a.attidentity,'dropped',a.attisdropped) ORDER BY d.refclassid,d.refobjid,d.refobjsubid,d.deptype) FROM pg_depend d LEFT JOIN pg_class rc ON d.refclassid='pg_class'::regclass AND rc.oid=d.refobjid LEFT JOIN pg_namespace rn ON rn.oid=rc.relnamespace LEFT JOIN pg_attribute a ON a.attrelid=rc.oid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid),'[]'::jsonb)
 ) ORDER BY n.nspname COLLATE "C",c.relname COLLATE "C") FROM pg_sequence q JOIN pg_class c ON c.oid=q.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=ANY($1::text[])),'[]'::jsonb)
 ) AS body
)
SELECT octet_length(body::text)::text AS byte_length,
 CASE WHEN octet_length(body::text)<=8388608 THEN body::text ELSE NULL END AS body FROM structure;
